<?php $edit = $sectionData['edit'] ?? null; $cover = $edit ? $this->imageUrl($edit['cover_image'] ?? '') : ''; ?>
<section class="admin-content">
  <div class="admin-section-intro"><div><span class="eyebrow">Editorial</span><h2><?= $edit ? 'Edit article' : 'Write an article' ?></h2><p>Draft content stays private; publishing makes the article available in the Knowledge Hub.</p></div></div>
  <form class="admin-form-card" method="post" action="<?= $this->escape(appUrl('/admin/articles/save')) ?>">
    <input type="hidden" name="csrf" value="<?= $this->escape($_SESSION['csrf'] ?? '') ?>"><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?>">
    <div class="form-grid"><div class="field"><label for="article-title">Article title *</label><input id="article-title" name="title" maxlength="200" value="<?= $this->escape($edit['title'] ?? '') ?>" required></div><div class="field"><label for="article-slug">URL slug *</label><input id="article-slug" name="slug" maxlength="220" value="<?= $this->escape($edit['slug'] ?? '') ?>" required></div></div>
    <div class="field"><label for="article-excerpt">Excerpt</label><textarea id="article-excerpt" name="excerpt" rows="3" maxlength="5000"><?= $this->escape($edit['excerpt'] ?? '') ?></textarea></div>
    <div class="field"><label for="article-content">Article content</label><textarea id="article-content" class="article-editor" name="content" rows="14" maxlength="100000"><?= $this->escape($edit['content'] ?? '') ?></textarea><small>Plain text. Line breaks are preserved on the public article page.</small></div>
    <div class="form-grid"><div class="field"><label for="article-cover">Cover image URL</label><input id="article-cover" name="cover_image" type="url" value="<?= $this->escape($edit['cover_image'] ?? '') ?>" placeholder="https://"><?php if ($cover !== ''): ?><img class="admin-cover-preview" src="<?= $this->escape($cover) ?>" alt="Current cover image"><?php endif ?></div><div class="field"><label for="article-status">Publication status</label><select id="article-status" name="status"><?php foreach (['draft'=>'Draft','published'=>'Published','archived'=>'Archived'] as $value=>$label): ?><option value="<?= $this->escape($value) ?>" <?= ($edit['status'] ?? 'draft') === $value ? 'selected' : '' ?>><?= $this->escape($label) ?></option><?php endforeach ?></select></div></div>
    <div class="admin-form-footer"><button class="button" type="submit"><?= $edit ? 'Save article' : 'Save draft' ?></button><?php if ($edit): ?><a class="button button-ghost" href="<?= $this->escape(appUrl('/admin/articles')) ?>">Cancel</a><?php endif ?></div>
  </form>
  <section class="admin-panel admin-record-panel"><div class="admin-panel-heading"><div><span class="eyebrow">Knowledge Hub</span><h2>Articles <span class="admin-count"><?= count($sectionData['records']) ?></span></h2></div></div>
    <?php if (!$sectionData['records']): ?><p class="admin-empty">No articles have been drafted.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Article</th><th>Slug</th><th>Published</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($sectionData['records'] as $record): ?><tr><td><strong><?= $this->escape($record['title']) ?></strong><small class="table-subtext"><?= $this->escape($record['excerpt'] ?: '') ?></small></td><td><?= $this->escape($record['slug']) ?></td><td><?= $record['published_at'] ? $this->escape(date('M j, Y', strtotime($record['published_at']))) : '—' ?></td><td><span class="status-badge status-<?= $this->escape($record['status']) ?>"><?= $this->escape(ucfirst($record['status'])) ?></span></td><td><a class="admin-icon-link" aria-label="Edit <?= $this->escape($record['title']) ?>" href="<?= $this->escape(appUrl('/admin/articles?id=' . (int) $record['id'])) ?>"><i data-lucide="pencil"></i></a><?php if ($record['status'] === 'published'): ?> <a class="admin-icon-link" aria-label="View <?= $this->escape($record['title']) ?>" href="<?= $this->escape(appUrl('/blog/' . $record['slug'])) ?>" target="_blank"><i data-lucide="external-link"></i></a><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
  </section>
</section>
